<?php $profile = $portal['profile']; ?>
<div class="page-heading student-heading"><div><p class="eyebrow">Parent Portal</p><h1><?= e($profile['first_name'] . ' ' . $profile['last_name']) ?></h1><p class="text-muted mb-0"><?= e($profile['relationship']) ?> · <?= e($profile['phone']) ?></p></div><button class="btn btn-outline-secondary" type="button" onclick="window.print()"><i class="bi bi-printer me-2"></i>Print</button></div>
<nav class="portal-nav mb-4"><a href="#children">My Children</a><a href="#fees">Fees</a><a href="#attendance">Attendance</a><a href="#results">Results</a><a href="#school">School Updates</a></nav>
<section class="metric-grid student-metrics"><article class="metric-card"><span class="metric-icon text-bg-primary"><i class="bi bi-people"></i></span><p>Linked Children</p><strong><?= e(count($portal['children'])) ?></strong></article><article class="metric-card"><span class="metric-icon text-bg-danger"><i class="bi bi-receipt"></i></span><p>Outstanding Fees</p><strong>KES <?= e(number_format(array_sum(array_map(static fn ($child) => array_sum(array_map(static fn ($invoice) => (float)$invoice['balance'], $child['invoices'])), $portal['children'])), 2)) ?></strong></article><article class="metric-card"><span class="metric-icon text-bg-success"><i class="bi bi-calendar-check"></i></span><p>Attendance Records</p><strong><?= e(array_sum(array_map(static fn ($child) => count($child['attendance']), $portal['children']))) ?></strong></article><article class="metric-card"><span class="metric-icon text-bg-info"><i class="bi bi-clipboard-data"></i></span><p>Results Available</p><strong><?= e(array_sum(array_map(static fn ($child) => count($child['results']), $portal['children']))) ?></strong></article></section>
<div class="row g-4 mt-1"><div class="col-12"><section id="children" class="panel"><div class="panel-header"><div><h2>My Children</h2><p>Academic profile and school information.</p></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Student</th><th>Admission No</th><th>Class</th><th>Status</th></tr></thead><tbody><?php foreach ($portal['children'] as $child): ?><tr><td class="fw-semibold"><?= e($child['first_name'] . ' ' . $child['last_name']) ?></td><td><?= e($child['admission_no']) ?></td><td><?= e($child['class_name'] ?? 'Unassigned') ?></td><td><span class="badge text-bg-success"><?= e($child['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<?php foreach ($portal['children'] as $child): ?><div class="col-12"><section class="panel"><div class="panel-header"><div><h2><?= e($child['first_name'] . ' ' . $child['last_name']) ?></h2><p><?= e($child['class_name'] ?? 'Class pending') ?></p></div></div><div class="row g-4"><div id="fees" class="col-lg-4"><h3 class="h6">Fees</h3><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Invoice</th><th>Balance</th></tr></thead><tbody><?php foreach ($child['invoices'] as $invoice): ?><tr><td><?= e($invoice['invoice_no']) ?></td><td>KES <?= e(number_format((float)$invoice['balance'], 2)) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div id="attendance" class="col-lg-4"><h3 class="h6">Attendance</h3><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach ($child['attendance'] as $record): ?><tr><td><?= e($record['attendance_date']) ?></td><td><?= e(ucfirst($record['status'])) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div id="results" class="col-lg-4"><h3 class="h6">Results</h3><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Exam</th><th>Subject</th><th>Grade</th></tr></thead><tbody><?php foreach ($child['results'] as $result): ?><tr><td><?= e($result['exam_name']) ?></td><td><?= e($result['subject_name']) ?></td><td><span class="badge text-bg-primary"><?= e($result['grade']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div></section></div><?php endforeach; ?>
<div id="school" class="col-lg-6"><section class="panel h-100"><div class="panel-header"><div><h2>Announcements</h2><p>Latest school notices.</p></div></div><div class="activity-list"><?php foreach ($portal['announcements'] as $announcement): ?><div class="activity-item"><span class="activity-dot"></span><div><strong><?= e($announcement['title']) ?></strong><p><?= e($announcement['body']) ?></p></div></div><?php endforeach; ?></div></section></div><div class="col-lg-6"><section class="panel h-100"><div class="panel-header"><div><h2>Upcoming Events</h2><p>Calendar highlights.</p></div></div><div class="activity-list"><?php foreach ($portal['events'] as $event): ?><div class="activity-item"><span class="activity-dot"></span><div><strong><?= e($event['title']) ?></strong><p><?= e(date('M j, Y H:i', strtotime($event['starts_at']))) ?><?= $event['location'] ? ' · ' . e($event['location']) : '' ?></p></div></div><?php endforeach; ?></div></section></div></div>
